CREATE TABLE strategy_definitions(definition_id uuid PRIMARY KEY,name text UNIQUE NOT NULL,kind text NOT NULL,purpose text NOT NULL,asset_scope text NOT NULL,decision_frequency text NOT NULL,rebalance_frequency text NOT NULL,benchmark text NOT NULL,owner text NOT NULL,invalidation_conditions jsonb NOT NULL);
CREATE TABLE strategy_versions(version_id uuid PRIMARY KEY,definition_id uuid NOT NULL REFERENCES strategy_definitions,version text NOT NULL,code_version text NOT NULL,required_features jsonb NOT NULL,default_parameters jsonb NOT NULL,active boolean NOT NULL,UNIQUE(definition_id,version));
CREATE TABLE strategy_runs(run_id uuid PRIMARY KEY,kind text NOT NULL,version_id uuid NOT NULL REFERENCES strategy_versions,decision_at timestamptz NOT NULL,universe_snapshot_id uuid NOT NULL,feature_set_id uuid NOT NULL,data_snapshot_id uuid NOT NULL,parameter_hash char(64) NOT NULL,input_hash char(64) UNIQUE NOT NULL,result_hash text NOT NULL,status text NOT NULL CHECK(status IN('CREATED','INPUTS_FROZEN','RUNNING','COMPLETED','FAILED','REJECTED')),cash_gate boolean NOT NULL,previous_run_id uuid,supersedes_run_id uuid);
CREATE TABLE strategy_scores(score_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES strategy_runs,instrument_id uuid NOT NULL REFERENCES instruments,raw_score numeric NOT NULL,rank integer NOT NULL CHECK(rank>0),UNIQUE(run_id,instrument_id));
CREATE TABLE strategy_candidates(candidate_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES strategy_runs,instrument_id uuid NOT NULL REFERENCES instruments,action text NOT NULL,raw_score numeric,rank integer,proposed_weight numeric NOT NULL CHECK(proposed_weight BETWEEN 0 AND 1),reason_codes jsonb NOT NULL,UNIQUE(run_id,instrument_id));
CREATE TABLE strategy_contributions(contribution_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES strategy_runs,instrument_id uuid NOT NULL REFERENCES instruments,feature_name text NOT NULL,feature_value numeric NOT NULL,weight numeric NOT NULL,contribution numeric NOT NULL,UNIQUE(run_id,instrument_id,feature_name));
CREATE TABLE research_evidence(evidence_id uuid PRIMARY KEY,strategy_version_id uuid NOT NULL REFERENCES strategy_versions,evidence_type text NOT NULL,sample_start text NOT NULL,sample_end text NOT NULL,artifact_ref text NOT NULL,parameters_hash text NOT NULL);
CREATE TABLE strategy_events(event_id uuid PRIMARY KEY,event_type text NOT NULL,run_id uuid NOT NULL,occurred_at timestamptz NOT NULL,reasons jsonb NOT NULL);
